// ❌ Vulnerable to XSS
let userInput = '<img src=x onerror=alert("XSS")>';
element.innerHTML = userInput;  // executes the script!

// ✅ Safe: use textContent
element.textContent = userInput;  // displays as plain text

// ✅ Sanitize with DOMPurify
import DOMPurify from "dompurify";
let clean = DOMPurify.sanitize(userInput);
element.innerHTML = clean;  // safe HTML

// ✅ Escape HTML entities manually
function escapeHtml(str) {
  return str.replace(/[&<>"']/g, (m) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;",
    '"': "&quot;", "'": "&#39;"
  }[m]));
}

// 1. CSRF Token approach
app.get("/form", (req, res) => {
  let token = generateCSRFToken();
  res.render("form", { csrfToken: token });
});

app.post("/transfer", (req, res) => {
  if (req.body.csrfToken !== req.session.csrfToken) {
    return res.status(403).send("Invalid CSRF token");
  }
  // Process the transfer...
});

// 2. SameSite cookie (defense in depth)
app.use(session({
  cookie: { sameSite: "strict", httpOnly: true, secure: true }
}));

// 3. Check Origin header
app.use((req, res, next) => {
  let origin = req.headers.origin || req.headers.referer;
  if (!origin?.startsWith("https://yoursite.com")) {
    return res.status(403).send("Forbidden");
  }
  next();
});

// CORS configuration
const cors = require("cors");

app.use(cors({
  origin: "https://yourapp.com",
  methods: ["GET", "POST", "PUT", "DELETE"],
  credentials: true
}));

// CSP headers
app.use((req, res, next) => {
  res.setHeader("Content-Security-Policy",
    "default-src 'self'; " +
    "script-src 'self' https://cdn.example.com; " +
    "style-src 'self' 'unsafe-inline'; " +
    "img-src 'self' data: https:; " +
    "connect-src 'self' https://api.example.com;"
  );
  next();
});
